CREATE OR REPLACE PROCEDURE sp(para_engineer_id integer, para_visit_start_text text, para_skill_id integer, para_part_fault_id integer, para_maintenance_contract_company_id integer, para_maintenance_contract_id integer) LANGUAGE plpgsql AS $$ DECLARE ref_cursor CURSOR FOR SELECT * FROM "Engineer_Visits"; ref_cursor2 CURSOR FOR SELECT * FROM "Skills_Required_To_Fix"; rec RECORD; rec2 RECORD; BEGIN UPDATE "Engineer_Visits" SET "engineer_id" = para_engineer_id + 76, "visit_start_text" = para_visit_start_text; DELETE FROM "Skills_Required_To_Fix" WHERE "skill_id" < para_skill_id; OPEN ref_cursor;
LOOP
  FETCH ref_cursor INTO rec;
  EXIT WHEN NOT FOUND;

  OPEN ref_cursor2;
  LOOP
    FETCH ref_cursor2 INTO rec2;
    EXIT WHEN NOT FOUND;

    IF rec2."skill_id" > para_maintenance_contract_company_id THEN
      UPDATE "Maintenance_Contracts"
      SET "maintenance_contract_id" = "maintenance_contract_id" - para_maintenance_contract_id - 33;
    END IF;
  END LOOP;
  CLOSE ref_cursor2;
END LOOP;
CLOSE ref_cursor;

UPDATE "Engineer_Visits"
SET "engineer_id" = para_engineer_id
WHERE para_part_fault_id <> -1000;

UPDATE "Fault_Log_Parts"
SET "fault_status" = 'Fixed'
WHERE para_part_fault_id = para_skill_id
  AND "part_fault_id" = para_part_fault_id;

UPDATE "Assets"
SET "other_asset_details" = para_visit_start_text
WHERE para_maintenance_contract_id <> -1000
  AND para_engineer_id < para_maintenance_contract_id
  AND "maintenance_contract_id" = para_maintenance_contract_id
  AND "supplier_company_id" = para_maintenance_contract_company_id;

UPDATE "Parts" p
SET "other_part_details" = para_visit_start_text
WHERE para_visit_start_text IS NOT NULL
  AND para_skill_id = para_maintenance_contract_company_id
  AND EXISTS (
    SELECT 1
    FROM "Part_Faults" pf
    WHERE pf."part_id" = p."part_id"
      AND pf."part_fault_id" = para_part_fault_id
  );

UPDATE "Fault_Log" fl
SET "other_fault_details" = para_visit_start_text
WHERE para_visit_start_text IS NOT NULL
  AND para_part_fault_id >= 0
  AND EXISTS (
    SELECT 1
    FROM "Assets" a
    JOIN "Asset_Parts" ap
      ON ap."asset_id" = a."asset_id"
    JOIN "Part_Faults" pf
      ON pf."part_id" = ap."part_id"
    WHERE a."asset_id" = fl."asset_id"
      AND a."maintenance_contract_id" = para_maintenance_contract_id
      AND a."supplier_company_id" = para_maintenance_contract_company_id
      AND pf."part_fault_id" = para_part_fault_id
  );
 END; $$;

